return [{json:{ok:true,result,resultText:text,usage:{promptTokens:Number(usage.prompt_tokens || usage.promptTokenCount || 0),completionTokens:Number(usage.completion_tokens || usage.candidatesTokenCount || 0),costUsd:0}}}];
